import{_ as l,o as i,c as e,ae as t}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"거래 분할 안내","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ko/guide/09-bill-split-guide.md","filePath":"v1/ko/guide/09-bill-split-guide.md"}'),r={name:"v1/ko/guide/09-bill-split-guide.md"};function o(n,a,s,h,d,u){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="거래-분할-안내" tabindex="-1">거래 분할 안내 <a class="header-anchor" href="#거래-분할-안내" aria-label="Permalink to &quot;거래 분할 안내&quot;">​</a></h1><h2 id="_1-어떤-기능인가요" tabindex="-1">1. 어떤 기능인가요? <a class="header-anchor" href="#_1-어떤-기능인가요" aria-label="Permalink to &quot;1. 어떤 기능인가요?&quot;">​</a></h2><p>한 번의 결제에 여러 용도가 함께 포함될 때(예: ‘마트/장보기’ 한 건에 과일과 생활용품이 함께 포함된 경우), 하나의 거래를 여러 개의 하위 거래로 분할해 분류 통계를 더 정확하게 만들 수 있습니다.</p><p>분할이 완료되면:</p><ul><li>여러 개의 ‘하위 거래’가 생성됩니다(각각 분류, 금액, 메모를 가짐).</li><li>원거래는 ‘분할 컨테이너’로 처리되어 목록 표시와 통계 합산에서 제외됩니다(중복 합산 방지).</li></ul><h2 id="_2-이런-경우에-유용해요" tabindex="-1">2. 이런 경우에 유용해요 <a class="header-anchor" href="#_2-이런-경우에-유용해요" aria-label="Permalink to &quot;2. 이런 경우에 유용해요&quot;">​</a></h2><ul><li>한 번의 결제에 여러 분류가 섞여 있는 경우(식비 + 생활용품, 교통 + 주차 등)</li><li>분류별 분석/예산 비교를 더 세밀하게 하고 싶은 경우</li><li>한 장의 영수증을 여러 분류/태그로 나눠 기록하고 싶은 경우</li></ul><h2 id="_3-사용-방법" tabindex="-1">3. 사용 방법 <a class="header-anchor" href="#_3-사용-방법" aria-label="Permalink to &quot;3. 사용 방법&quot;">​</a></h2><ol><li>거래 목록에서 분할할 거래를 찾습니다</li><li>해당 거래를 왼쪽으로 스와이프한 뒤 <strong>분할</strong>을 선택합니다</li><li><strong>거래 분할</strong> 화면에서: <ul><li>각 항목의 <strong>분류</strong>를 눌러 분류를 선택합니다</li><li><strong>금액</strong>을 눌러 각 항목의 금액을 입력합니다</li><li>메모는 선택 사항입니다(추가 설명용)</li><li>항목이 더 필요하면 <strong>항목 추가</strong>를 누릅니다</li></ul></li><li><strong>남은 배분 금액</strong>이 0인지 확인합니다(하위 항목 합계가 원금액과 일치)</li><li>우측 상단의 <strong>완료/저장</strong>을 누릅니다</li></ol><h2 id="_4-규칙-및-주의사항" tabindex="-1">4. 규칙 및 주의사항 <a class="header-anchor" href="#_4-규칙-및-주의사항" aria-label="Permalink to &quot;4. 규칙 및 주의사항&quot;">​</a></h2><ul><li>하위 항목 금액의 합계는 원거래 금액과 같아야 하며, 그렇지 않으면 저장할 수 없습니다.</li><li>각 하위 항목은 분류 선택이 필요하며, 금액은 0보다 커야 합니다.</li><li>통계는 하위 거래를 기준으로 계산되며, 원거래는 통계에 포함되지 않습니다.</li><li>다단계 분할을 지원합니다. 하위 거래도 다시 분할할 수 있으며, 최종 통계는 마지막 단계(리프) 하위 거래를 기준으로 계산됩니다.</li><li>거래 분할과 정산(报销)은 상호 배타적입니다. 정산 대상/정산 완료 상태의 지출은 분할할 수 없고, 이미 분할된 거래(하위 거래/분할 컨테이너 포함)는 정산 절차를 시작할 수 없습니다. 먼저 정산이 필요한지 결정한 뒤 분할 여부를 선택하세요.</li></ul><h2 id="_5-자주-묻는-질문" tabindex="-1">5. 자주 묻는 질문 <a class="header-anchor" href="#_5-자주-묻는-질문" aria-label="Permalink to &quot;5. 자주 묻는 질문&quot;">​</a></h2><h3 id="q1-분할-후-원거래는-어디로-가나요" tabindex="-1">Q1. 분할 후 원거래는 어디로 가나요? <a class="header-anchor" href="#q1-분할-후-원거래는-어디로-가나요" aria-label="Permalink to &quot;Q1. 분할 후 원거래는 어디로 가나요?&quot;">​</a></h3><p>중복 합산을 방지하기 위해 원거래는 ‘분할 컨테이너’로 표시되며, 보통 목록에 노출되지 않습니다. 통계는 하위 거래를 기준으로 계산됩니다.</p><h3 id="q2-일부만-분할할-수도-있나요" tabindex="-1">Q2. 일부만 분할할 수도 있나요? <a class="header-anchor" href="#q2-일부만-분할할-수도-있나요" aria-label="Permalink to &quot;Q2. 일부만 분할할 수도 있나요?&quot;">​</a></h3><p>가능합니다. 한 줄을 ‘기타/원 분류’로 남겨 두고, 금액을 남은 금액으로 입력하면 됩니다. 핵심은 하위 항목의 합계가 원금액과 일치해야 한다는 점입니다.</p><h3 id="q3-분할-후에도-수정할-수-있나요" tabindex="-1">Q3. 분할 후에도 수정할 수 있나요? <a class="header-anchor" href="#q3-분할-후에도-수정할-수-있나요" aria-label="Permalink to &quot;Q3. 분할 후에도 수정할 수 있나요?&quot;">​</a></h3><p>보통은 하위 거래(금액/분류/메모 등)를 직접 수정하는 것을 권장합니다. 다시 분할해야 한다면, 관련 하위 거래를 삭제한 뒤 재분할하는 방식이 일반적입니다.</p>',18)])])}const p=l(r,[["render",o]]);export{c as __pageData,p as default};
